PRODUCTION_SOURCE = '"""\nOLA-034\nOracle Live Market Lineage Pipeline Bridge\n\nCanonical integration boundary connecting live canonical market observations to:\n- OLA-031 exact live market-state fingerprinting\n- OLA-033 per-market canonical lineage ledger\n\nPurpose:\n- accept canonical market_snapshot observations from the live acquisition path\n- derive exact OLA-031 market-state identity\n- append one deterministic frame into the OLA-033 lineage ledger\n- return one immutable bridge receipt binding observation, fingerprint,\n  lineage head, dwell, and transition identity\n\nThis bridge owns no persistence and performs no intelligence interpretation,\nsignal scoring, alerting, Q Series handoff, authorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime\nfrom hashlib import sha256\nimport json\nfrom typing import Any\n\nfrom .oracle_canonical_market_lineage_ledger import (\n    MarketLineageLedgerContractError,\n    MarketLineageLedgerInvariantError,\n    OracleCanonicalMarketLineageLedger,\n)\nfrom .oracle_canonical_market_state_fingerprint_contract import (\n    CanonicalMarketStateFingerprint,\n    MarketStateFingerprintContractError,\n    MarketStateFingerprintInvariantError,\n    OracleCanonicalMarketStateFingerprintContract,\n)\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-034"\nENGINE_ID = "OLA-034"\nBRIDGE_RECEIPT_TYPE = "oracle_live_market_lineage_pipeline_receipt"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass LiveMarketLineagePipelineContractError(ValueError):\n    """Raised when OLA-034 pipeline input is malformed."""\n\n\nclass LiveMarketLineagePipelineInvariantError(RuntimeError):\n    """Raised when permanent OLA-034 invariants are violated."""\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass LiveMarketLineagePipelineReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    source_id: str\n    source_market_id: str\n    observation_id: str\n    fingerprint_id: str\n    market_state_hash: str\n    previous_market_state_hash: str | None\n    lineage_hash: str\n    previous_lineage_hash: str | None\n    transition_detected: bool\n    transition_id: str | None\n    consecutive_frame_count: int\n    state_first_observed_at: str\n    state_last_observed_at: str\n    state_changed_at: str | None\n    dwell_seconds: str\n    ledger_market_count: int\n    ledger_record_count: int\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    receipt_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise LiveMarketLineagePipelineInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise LiveMarketLineagePipelineInvariantError(\n                "engine identity invariant violated"\n            )\n        if self.receipt_type != BRIDGE_RECEIPT_TYPE:\n            raise LiveMarketLineagePipelineInvariantError(\n                "receipt type invariant violated"\n            )\n        if self.consecutive_frame_count <= 0:\n            raise LiveMarketLineagePipelineInvariantError(\n                "consecutive frame count must be positive"\n            )\n        if self.ledger_market_count <= 0:\n            raise LiveMarketLineagePipelineInvariantError(\n                "ledger market count must be positive"\n            )\n        if self.ledger_record_count <= 0:\n            raise LiveMarketLineagePipelineInvariantError(\n                "ledger record count must be positive"\n            )\n\n        if self.transition_detected:\n            if self.previous_market_state_hash is None:\n                raise LiveMarketLineagePipelineInvariantError(\n                    "transition requires previous market state hash"\n                )\n            if self.transition_id is None:\n                raise LiveMarketLineagePipelineInvariantError(\n                    "transition requires transition identity"\n                )\n            if self.state_changed_at is None:\n                raise LiveMarketLineagePipelineInvariantError(\n                    "transition requires state_changed_at"\n                )\n        else:\n            if self.transition_id is not None:\n                raise LiveMarketLineagePipelineInvariantError(\n                    "non-transition cannot carry transition identity"\n                )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise LiveMarketLineagePipelineInvariantError(\n                "OLA-034 read-only authority invariants violated"\n            )\n\n\nclass OracleLiveMarketLineagePipelineBridge:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        ledger: OracleCanonicalMarketLineageLedger | None = None,\n    ) -> None:\n        self._fingerprint_contract = (\n            OracleCanonicalMarketStateFingerprintContract()\n        )\n        self._ledger = (\n            ledger\n            if ledger is not None\n            else OracleCanonicalMarketLineageLedger()\n        )\n\n        if not isinstance(\n            self._ledger,\n            OracleCanonicalMarketLineageLedger,\n        ):\n            raise LiveMarketLineagePipelineContractError(\n                "ledger must be an OLA-033 "\n                "OracleCanonicalMarketLineageLedger"\n            )\n\n    @property\n    def ledger(self) -> OracleCanonicalMarketLineageLedger:\n        return self._ledger\n\n    def process(\n        self,\n        *,\n        observation: CanonicalObservation,\n        frame_observed_at: datetime,\n    ) -> LiveMarketLineagePipelineReceipt:\n        if not isinstance(observation, CanonicalObservation):\n            raise LiveMarketLineagePipelineContractError(\n                "observation must be a canonical live acquisition observation"\n            )\n\n        if observation.observation_type != "market_snapshot":\n            raise LiveMarketLineagePipelineContractError(\n                "OLA-034 accepts only market_snapshot observations"\n            )\n\n        try:\n            fingerprint = self._fingerprint_contract.fingerprint(\n                observation=observation\n            )\n        except MarketStateFingerprintContractError as exc:\n            raise LiveMarketLineagePipelineContractError(\n                f"OLA-031 fingerprint contract rejected observation: {exc}"\n            ) from exc\n        except MarketStateFingerprintInvariantError as exc:\n            raise LiveMarketLineagePipelineInvariantError(\n                f"OLA-031 fingerprint invariant failed: {exc}"\n            ) from exc\n\n        self._assert_fingerprint_binding(\n            observation=observation,\n            fingerprint=fingerprint,\n        )\n\n        try:\n            ledger_receipt = self._ledger.append(\n                fingerprint=fingerprint,\n                frame_observed_at=frame_observed_at,\n            )\n        except MarketLineageLedgerContractError as exc:\n            raise LiveMarketLineagePipelineContractError(\n                f"OLA-033 lineage ledger rejected frame: {exc}"\n            ) from exc\n        except MarketLineageLedgerInvariantError as exc:\n            raise LiveMarketLineagePipelineInvariantError(\n                f"OLA-033 lineage ledger invariant failed: {exc}"\n            ) from exc\n\n        lineage = self._ledger.head(\n            source_id=fingerprint.source_id,\n            source_market_id=fingerprint.source_market_id,\n        )\n\n        if lineage is None:\n            raise LiveMarketLineagePipelineInvariantError(\n                "OLA-033 accepted frame but lineage head is missing"\n            )\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": BRIDGE_RECEIPT_TYPE,\n            "source_id": lineage.source_id,\n            "source_market_id": lineage.source_market_id,\n            "observation_id": lineage.observation_id,\n            "fingerprint_id": lineage.fingerprint_id,\n            "market_state_hash": lineage.current_market_state_hash,\n            "previous_market_state_hash": (\n                lineage.previous_market_state_hash\n            ),\n            "lineage_hash": lineage.lineage_hash,\n            "previous_lineage_hash": lineage.previous_lineage_hash,\n            "transition_detected": lineage.transition_detected,\n            "transition_id": lineage.transition_id,\n            "consecutive_frame_count": lineage.consecutive_frame_count,\n            "state_first_observed_at": (\n                lineage.state_first_observed_at.isoformat()\n            ),\n            "state_last_observed_at": (\n                lineage.state_last_observed_at.isoformat()\n            ),\n            "state_changed_at": (\n                None\n                if lineage.state_changed_at is None\n                else lineage.state_changed_at.isoformat()\n            ),\n            "dwell_seconds": lineage.dwell_seconds,\n            "ledger_market_count": ledger_receipt.ledger_market_count,\n            "ledger_record_count": ledger_receipt.ledger_record_count,\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = LiveMarketLineagePipelineReceipt(\n            **payload,\n            receipt_hash=_stable_hash(payload),\n        )\n        receipt.assert_invariants()\n        return receipt\n\n    @staticmethod\n    def _assert_fingerprint_binding(\n        *,\n        observation: CanonicalObservation,\n        fingerprint: CanonicalMarketStateFingerprint,\n    ) -> None:\n        if fingerprint.observation_id != observation.observation_id:\n            raise LiveMarketLineagePipelineInvariantError(\n                "fingerprint observation identity binding violated"\n            )\n        if fingerprint.source_id != observation.source_id:\n            raise LiveMarketLineagePipelineInvariantError(\n                "fingerprint source identity binding violated"\n            )\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_market_lineage_pipeline_bridge import (\n    LiveMarketLineagePipelineContractError,\n    OracleLiveMarketLineagePipelineBridge,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 7, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 7, 0, 10, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 14, 7, 0, 20, tzinfo=timezone.utc)\nT4 = datetime(2026, 7, 14, 7, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id="batch.ola.034." + frame_id,\n    )\n\n\ndef run_same_state_pipeline_test():\n    bridge = OracleLiveMarketLineagePipelineBridge()\n\n    first = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-A",\n            frame_id="a1",\n        ),\n        frame_observed_at=T1,\n    )\n    second = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-A",\n            frame_id="a2",\n        ),\n        frame_observed_at=T2,\n    )\n\n    assert first.transition_detected is False\n    assert second.transition_detected is False\n    assert first.market_state_hash == second.market_state_hash\n    assert second.consecutive_frame_count == 2\n    assert second.dwell_seconds == "10.000000"\n    assert second.previous_lineage_hash == first.lineage_hash\n\n    return bridge, first, second\n\n\ndef run_transition_pipeline_test():\n    bridge, _, second = run_same_state_pipeline_test()\n\n    changed = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-A",\n            frame_id="a3",\n            yes_ask="0.7770",\n        ),\n        frame_observed_at=T3,\n    )\n\n    assert changed.transition_detected is True\n    assert (\n        changed.previous_market_state_hash\n        == second.market_state_hash\n    )\n    assert changed.market_state_hash != second.market_state_hash\n    assert changed.transition_id is not None\n    assert changed.state_changed_at == T3.isoformat()\n    assert changed.consecutive_frame_count == 1\n    assert changed.dwell_seconds == "0.000000"\n\n    return bridge, changed\n\n\ndef run_interleaved_market_pipeline_test():\n    bridge = OracleLiveMarketLineagePipelineBridge()\n\n    a1 = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-A",\n            frame_id="ia1",\n        ),\n        frame_observed_at=T1,\n    )\n    b1 = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-B",\n            frame_id="ib1",\n        ),\n        frame_observed_at=T1,\n    )\n    a2 = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-A",\n            frame_id="ia2",\n        ),\n        frame_observed_at=T2,\n    )\n    b2 = bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-B",\n            frame_id="ib2",\n            yes_ask="0.9000",\n        ),\n        frame_observed_at=T2,\n    )\n\n    assert a1.source_market_id == "KXTEST-PIPE-A"\n    assert b1.source_market_id == "KXTEST-PIPE-B"\n    assert a2.transition_detected is False\n    assert a2.consecutive_frame_count == 2\n    assert b2.transition_detected is True\n    assert bridge.ledger.market_count == 2\n    assert bridge.ledger.record_count == 4\n\n    return bridge\n\n\ndef run_duplicate_observation_translation_test():\n    bridge = OracleLiveMarketLineagePipelineBridge()\n    observation = build_observation(\n        market_id="KXTEST-PIPE-DUP",\n        frame_id="dup1",\n    )\n\n    bridge.process(\n        observation=observation,\n        frame_observed_at=T1,\n    )\n\n    try:\n        bridge.process(\n            observation=observation,\n            frame_observed_at=T2,\n        )\n        raise AssertionError(\n            "duplicate observation must fail closed"\n        )\n    except LiveMarketLineagePipelineContractError:\n        pass\n\n    assert bridge.ledger.record_count == 1\n\n\ndef run_clock_regression_translation_test():\n    bridge = OracleLiveMarketLineagePipelineBridge()\n\n    bridge.process(\n        observation=build_observation(\n            market_id="KXTEST-PIPE-CLOCK",\n            frame_id="clock1",\n        ),\n        frame_observed_at=T3,\n    )\n\n    try:\n        bridge.process(\n            observation=build_observation(\n                market_id="KXTEST-PIPE-CLOCK",\n                frame_id="clock2",\n            ),\n            frame_observed_at=T2,\n        )\n        raise AssertionError(\n            "clock regression must fail closed at OLA-034 boundary"\n        )\n    except LiveMarketLineagePipelineContractError:\n        pass\n\n    assert bridge.ledger.record_count == 1\n\n\ndef run_wrong_observation_type_test():\n    payload = {\n        "source_market_id": "KXTEST-WRONG-TYPE",\n        "yes_bid_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id="kalshi.wrong.type",\n        observed_at=T1,\n        observation_type="event_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n        },\n    )\n\n    observation = CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id="batch.ola.034.wrong",\n    )\n\n    bridge = OracleLiveMarketLineagePipelineBridge()\n\n    try:\n        bridge.process(\n            observation=observation,\n            frame_observed_at=T1,\n        )\n        raise AssertionError(\n            "wrong observation type must fail closed"\n        )\n    except LiveMarketLineagePipelineContractError:\n        pass\n\n    assert bridge.ledger.record_count == 0\n\n\ndef run_deterministic_receipt_test():\n    first_bridge = OracleLiveMarketLineagePipelineBridge()\n    second_bridge = OracleLiveMarketLineagePipelineBridge()\n\n    first_receipts = []\n    second_receipts = []\n\n    frames = (\n        (\n            build_observation(\n                market_id="KXTEST-PIPE-REPLAY",\n                frame_id="r1",\n            ),\n            T1,\n        ),\n        (\n            build_observation(\n                market_id="KXTEST-PIPE-REPLAY",\n                frame_id="r2",\n            ),\n            T2,\n        ),\n        (\n            build_observation(\n                market_id="KXTEST-PIPE-REPLAY",\n                frame_id="r3",\n                yes_ask="0.8100",\n            ),\n            T3,\n        ),\n        (\n            build_observation(\n                market_id="KXTEST-PIPE-REPLAY",\n                frame_id="r4",\n                yes_ask="0.8100",\n            ),\n            T4,\n        ),\n    )\n\n    for observation, observed_at in frames:\n        first_receipts.append(\n            first_bridge.process(\n                observation=observation,\n                frame_observed_at=observed_at,\n            )\n        )\n        second_receipts.append(\n            second_bridge.process(\n                observation=observation,\n                frame_observed_at=observed_at,\n            )\n        )\n\n    assert first_receipts == second_receipts\n    assert (\n        first_bridge.ledger.records()\n        == second_bridge.ledger.records()\n    )\n\n    return first_receipts\n\n\ndef main():\n    _, first, second = run_same_state_pipeline_test()\n    _, changed = run_transition_pipeline_test()\n    interleaved = run_interleaved_market_pipeline_test()\n\n    run_duplicate_observation_translation_test()\n    run_clock_regression_translation_test()\n    run_wrong_observation_type_test()\n\n    replay_receipts = run_deterministic_receipt_test()\n\n    result = {\n        "schema_version": changed.schema_version,\n        "engine_id": changed.engine_id,\n        "status": "passed",\n        "canonical_market_snapshot_consumed": True,\n        "ola_031_exact_fingerprint_derived": True,\n        "ola_033_lineage_ledger_appended": True,\n        "observation_to_fingerprint_binding_preserved": True,\n        "same_state_dwell_preserved": (\n            second.dwell_seconds == "10.000000"\n        ),\n        "same_state_consecutive_frames_preserved": (\n            second.consecutive_frame_count == 2\n        ),\n        "exact_state_transition_preserved": (\n            changed.transition_detected\n        ),\n        "previous_market_state_hash_preserved": (\n            changed.previous_market_state_hash\n            == second.market_state_hash\n        ),\n        "transition_identity_preserved": (\n            changed.transition_id is not None\n        ),\n        "interleaved_market_lineage_isolated": (\n            interleaved.ledger.market_count == 2\n        ),\n        "duplicate_observation_fails_closed": True,\n        "clock_regression_fails_closed": True,\n        "dependency_contract_errors_translated": True,\n        "wrong_observation_type_fails_closed": True,\n        "deterministic_receipt_replay_valid": (\n            len(replay_receipts) == 4\n        ),\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": changed.read_only,\n        "execution_allowed": changed.execution_allowed,\n        "execution_adapter_resolved": (\n            changed.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            changed.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            changed.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            changed.order_placement_allowed\n        ),\n        "funds_moved": changed.funds_moved,\n        "portfolio_mutated": changed.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-034 Oracle Live Market Lineage "\n        "Pipeline Bridge"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-034 INSTALLER")
    print(" ORACLE LIVE MARKET LINEAGE PIPELINE")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-034 Oracle Live Market Lineage "
        "Pipeline Bridge installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_034_oracle_live_market_"
        "lineage_pipeline_bridge.py"
    )


if __name__ == "__main__":
    main()
